const excludedSDKInputNames = new Set(['node_modules','Tests','evidence','.git']);
const includesSDKInputName = name => !excludedSDKInputNames.has(name) && !name.includes('.bak.');
const exampleSourceRoot = 'Scripts/MiniApps/Examples';
// These are output roots of the public authoring/Metro tools, not arbitrary
// resource names. Authored build/dist directories and resource ZIPs survive.
const exampleOutputRoots = new Set(['.hanlin-build','.hanlin-authoring','.metro-cache']);
const includesSDKSourcePath = relative => {
  if (!relative.split('/').every(includesSDKInputName)) return false;
  if (!relative.startsWith(exampleSourceRoot+'/')) return true;
  const [,projectChild] = relative.slice(exampleSourceRoot.length+1).split('/');
  return !exampleOutputRoots.has(projectChild);
};

export async function inputReceipt(root=repositoryRoot) {
  const files=[];
  for(const relative of sdkInputs) {
    const bytes=await readFile(path.join(root,relative));
    files.push({path:relative,sha256:sha(bytes)});
  }
  for(const relative of ['Scripts/MiniApps','Packages/HanlinExpoUI','Packages/HanlinExpoNativeAPIJS',
    'Packages/HanlinNativeScriptRuntime/Sources/HanlinNativeScriptRuntime/Resources/NativeScriptSharedRuntime/@hanlin/host-services',
    'Packages/HanlinPlatform/Sources/HanlinScriptWidgetOriginal',
    'Packages/HanlinExpoRuntime/Sources/ExpoWidgets',
    'Packages/HanlinPlatform/Sources/HanlinScriptExtensions/ScriptWidget/HanlinScriptWidgetRuntime.swift',
    'docs/miniapp-sdk','docs/hanlin-nativescript-guide.md','docs/hanlin-expo-runtime.md']) {
    files.push(...await collectSDKSourceInputs(path.join(root,relative),relative));
  }
  const unique=[...new Map(files.map(f=>[f.path,f])).values()].sort((a,b)=>a.path.localeCompare(b.path));
  return {files:unique,sha256:sha(JSON.stringify(unique))};
}

const destination = path.join(root, 'docs/miniapp-sdk/source-inventory.json');
const manifestReference = path.join(root, 'docs/miniapp-sdk/MANIFEST_REFERENCE.md');
const files = new Map();
const compare = (a, b) => a < b ? -1 : a > b ? 1 : 0;
const relative = file => path.relative(root, file).replaceAll('\\', '/');
async function source(file) {
  file = path.resolve(root, file);
  if (!files.has(file)) {
    const bytes = await readFile(file);
    files.set(file, {path: relative(file), sha256: createHash('sha256').update(bytes).digest('hex'), text: bytes.toString('utf8')});
  }
  return files.get(file);
}

const preparedWidgetPublication = await source('Packages/HanlinPlatform/Sources/HanlinScriptExtensions/HanlinExpoWidgetPublication.swift');
const preparedWidgetConsumer = await source('Packages/HanlinPlatform/Sources/HanlinScriptExtensions/HanlinPreparedWidget.swift');
const generatedViewProducer = await source('Packages/HanlinSwiftUIBridgeGenerator/Sources/HanlinSwiftUIBridgeCore/OutputGenerator.swift');

  sources: [...files.values()].map(({path, sha256}) => ({path, sha256})).sort((a, b) => compare(a.path, b.path)),
};
if (process.argv.includes('--check')) {
  const prior = JSON.parse(await readFile(destination, 'utf8'));
  delete prior.sourceCommit;
  delete prior.uncommittedSourcePaths;
  if (JSON.stringify(prior) !== JSON.stringify(inventory)) throw new Error('SDK source inventory drift. Audit source changes, then regenerate with --write.');
  if (await readFile(manifestReference, 'utf8') !== manifestMarkdown) throw new Error('Manifest field reference drift. Regenerate with --write after source review.');
  console.log(`PASS: SDK source inventory matches ${inventory.sources.length} sources and ${exports.length} local public exports.`);
} else if (process.argv.includes('--write')) {
  const sourceCommit = execFileSync('git', ['rev-parse', 'HEAD'], {cwd: root, encoding: 'utf8'}).trim();
  const changed = execFileSync('git', ['status', '--porcelain', '--untracked-files=all'], {cwd: root, encoding: 'utf8'})
    .split('\n').filter(Boolean).map(line => line.slice(3).replaceAll('\\', '/'));
  const uncommittedSourcePaths = inventory.sources.map(s => s.path).filter(p => changed.includes(p));
  await mkdir(path.dirname(destination), {recursive: true});
  await writeFile(destination, JSON.stringify({sourceCommit, uncommittedSourcePaths, ...inventory}, null, 2) + '\n');
  await writeFile(manifestReference, manifestMarkdown);
  console.log(`Wrote source inventory: ${inventory.sources.length} sources, ${exports.length} local public exports; E2E not inferred.`);
} else throw new Error('Use --check for read-only drift verification or --write after auditing changes.');

def build() -> dict:
    sources = TrackedSources(ROOT)
    sdk = json.loads(sources.read_text("docs/miniapp-sdk/source-inventory.json"))
    sources.prefetch(entry["path"] for entry in sdk["sources"])
    for entry in sdk["sources"]:
        if hashlib.sha256(sources.read_bytes(entry["path"])).hexdigest() != entry["sha256"]:
            raise ValueError(f"SDK authority is stale: {entry['path']}; run its source audit first.")
    refs = {}

    def ref(name: str, file: str, anchor: str) -> str:
        data = sources.read_bytes(file)
        text = data.decode("utf-8")
        if anchor not in text:
            raise ValueError(f"Audit anchor changed: {file}: {anchor}")
        refs[name] = {"file": file, "line": text[:text.index(anchor)].count("\n") + 1,
                      "anchor": anchor, "sha256": hashlib.sha256(data).hexdigest()}
